SELECT
  base.geo_level,
  base.geo_id,
  base.geo_name,
  base.year,
  base.median_hh_income AS metric_value,
  'median_hh_income' AS metric_id,
  'Median Household Income' AS metric_label,
  ROW_NUMBER() OVER (
    ORDER BY base.median_hh_income DESC, base.geo_name ASC
  ) AS rank
FROM gold.economics_income_wide AS base
WHERE base.geo_level = 'state' AND base.year = 2023 AND base.median_hh_income IS NOT NULL
ORDER BY metric_value DESC, geo_name ASC
LIMIT 10
